const chatIconViewBox = computed(() => {
  if (
    props.name === 'librarySearch'
    || props.name === 'libraryFilter'
    || props.name === 'libraryGrid'
    || props.name === 'libraryList'
  ) return '0 0 20 20'
  if (props.name === 'chatCheck') return '0 0 16 16'
  if (props.name === 'chatHistoryPinSmall') return '0 0 16 16'
